using System.ComponentModel.DataAnnotations;
using BofcBackend.Api.Common.Exceptions;
using BofcBackend.Api.Domain.Entities;
using BofcBackend.Api.Features.Settings.Models;

// SPEC: spec-a6f59e - the "Auto generated match number" setting: default 2, only 1 to 8 is
// stored, and a save that leaves the field out keeps the stored value instead of resetting it.
public static class AutoGeneratedMatchNumberTests
{
    public static (string Name, Func<Task> Run)[] All =>
    [
        ("never-saved settings default Auto generated match number to 2", () =>
        {
            AssertValue(new SystemSettings { Id = 1 }, 2);
            return Task.CompletedTask;
        }),
        ("Auto generated match number rejects 0 and 9 and keeps the stored value", () =>
        {
            foreach (var invalid in new[] { 0, 9 })
            {
                var settings = new SystemSettings { Id = 1, AutoGeneratedMatchNumber = 5 };
                try
                {
                    settings.ApplyAutoGeneratedMatchNumber(invalid);
                    throw new Exception($"{invalid} was accepted");
                }
                catch (BadRequestException)
                {
                }
                AssertValue(settings, 5);
            }
            return Task.CompletedTask;
        }),
        ("Auto generated match number stores every value from 1 to 8", () =>
        {
            for (var n = 1; n <= 8; n++)
            {
                var settings = new SystemSettings { Id = 1 };
                settings.ApplyAutoGeneratedMatchNumber(n);
                AssertValue(settings, n);
            }
            return Task.CompletedTask;
        }),
        ("a save without Auto generated match number keeps the stored value", () =>
        {
            var settings = new SystemSettings { Id = 1, AutoGeneratedMatchNumber = 6 };
            settings.ApplyAutoGeneratedMatchNumber(null);
            AssertValue(settings, 6);
            return Task.CompletedTask;
        }),
        ("the settings request validates Auto generated match number to 1-8 or omitted", () =>
        {
            foreach (var (value, valid) in new (int?, bool)[] { (0, false), (9, false), (1, true), (8, true), (null, true) })
            {
                var request = new UpdateSystemSettingsRequest { AutoGeneratedMatchNumber = value };
                var ok = Validator.TryValidateObject(request, new ValidationContext(request), new List<ValidationResult>(), validateAllProperties: true);
                if (ok != valid)
                {
                    throw new Exception($"{value?.ToString() ?? "null"}: expected {(valid ? "valid" : "invalid")}, got {(ok ? "valid" : "invalid")}");
                }
            }
            return Task.CompletedTask;
        }),
    ];

    private static void AssertValue(SystemSettings settings, int expected)
    {
        if (settings.AutoGeneratedMatchNumber != expected)
        {
            throw new Exception($"expected {expected}, got {settings.AutoGeneratedMatchNumber}");
        }
    }
}
